func (q *Queries) StartTaskInteractionResolution(ctx context.Context, arg StartTaskInteractionResolutionParams) (TaskInteraction, error) {
	row := q.db.QueryRow(ctx, startTaskInteractionResolution, arg.ResponseRequestID, arg.Response, arg.ID)
	var i TaskInteraction
	err := row.Scan(
		&i.ID,
		&i.WorkspaceID,
		&i.RuntimeID,
		&i.ChatSessionID,
		&i.TaskID,
		&i.RunID,
		&i.TurnID,
		&i.Kind,
		&i.Status,
		&i.Version,
		&i.Request,
		&i.ResponseRequestID,
		&i.Response,
		&i.CreatedAt,
		&i.UpdatedAt,
		&i.ExpiresAt,
	)
	return i, err
}
